import React from 'react';

const Education = () => {
    return (
        <div>
            <h2>Education</h2>
            <ul>
                <li>
                    <strong>University Name</strong> - Degree (Year)
                    <p>Relevant courses: Course 1, Course 2, Course 3</p>
                </li>
                <li>
                    <strong>High School Name</strong> - Diploma (Year)
                    <p>Relevant courses: Course 1, Course 2</p>
                </li>
            </ul>
        </div>
    );
};

export default Education;
